script:
(function () {
  'use strict';
  // Cost of waiting: two savers with the same plan and the same end date. One starts now, the other
  // waits W years, then puts in the same starting amount and the same regular contribution.
  // Returns compound once per contribution period at (annual return / periods per year);
  // contributions are made at the end of each period.
  //   FV(start, pmt, i, n) = start(1+i)^n + pmt((1+i)^n - 1)/i      (i = 0: start + pmt n)
  //   Start now: n = years x f periods. Wait: n = (years - W) x f periods.
  //   Catch-up contribution = (FV_now - start(1+i)^n_wait) / (((1+i)^n_wait - 1)/i)
  // Verified (Node scratch test vs independent Python closed form): $100/month at 6% for 30 years
  //   = $100,451.50 and for 25 years = $69,299.40 (standard annuity-table values), so waiting
  //   5 years costs $31,152; catching up needs $100,451.50 / 693.00 = $144.95/month. $1,000/year
  //   at 6%: 10 years $13,180.79 vs 8 years $9,897.47. 0% return: cost = only the missed deposits.
  //   Delay >= saving period, negative or blank inputs show an error instead of NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var FREQ_NAMES = { 52: 'week', 26: 'two weeks', 12: 'month', 4: 'quarter', 1: 'year' };

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function fv(start, pmt, i, n) {
    if (n <= 0) return start;
    if (i === 0) return start + pmt * n;
    var g = Math.pow(1 + i, n);
    return start * g + pmt * (g - 1) / i;
  }

  function catchUp(target, start, i, n) {
    if (n <= 0) return NaN;
    var need = target - start * Math.pow(1 + i, n);
    if (need <= 0) return 0;
    return i === 0 ? need / n : need / ((Math.pow(1 + i, n) - 1) / i);
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function cell(tr, text) {
    var td = document.createElement('td');
    td.textContent = text;
    tr.appendChild(td);
  }

  function update() {
    var start = num('ddStart'), pmt = num('ddContribution'), years = Math.round(num('ddYears')),
        wait = Math.round(num('ddWait')), rate = num('ddRate'),
        f = parseInt(document.getElementById('ddFrequency').value, 10);
    var error = document.getElementById('ddError');
    var msg = '';
    if ([start, pmt, years, wait, rate].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (start < 0 || pmt < 0) msg = 'Amounts cannot be negative.';
    else if (start === 0 && pmt === 0) msg = 'Enter a starting amount, a regular contribution or both.';
    else if (years < 1 || years > 70) msg = 'Enter a saving period from 1 to 70 years.';
    else if (wait < 1 || wait >= years) msg = 'The delay must be at least 1 year and shorter than the saving period.';
    else if (rate < 0 || rate > 50) msg = 'Enter a rate of return from 0 to 50%.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var i = rate / 100 / f, nNow = years * f, nWait = (years - wait) * f;
    var now = fv(start, pmt, i, nNow), later = fv(start, pmt, i, nWait);
    var putNow = start + pmt * nNow, putLater = start + pmt * nWait;
    var cost = now - later;
    var needed = catchUp(now, start, i, nWait);

    set('ddCost', money0.format(cost));
    set('ddNow', money0.format(now));
    set('ddLater', money0.format(later));
    set('ddLaterLabel', 'If you wait ' + wait + (wait === 1 ? ' year' : ' years'));
    set('ddPutNow', money0.format(putNow));
    set('ddPutLater', money0.format(putLater));
    set('ddGrowthNow', money0.format(now - putNow));
    set('ddGrowthLater', money0.format(later - putLater));
    set('ddMissed', money0.format(putNow - putLater));
    set('ddLostGrowth', money0.format(cost - (putNow - putLater)));
    set('ddCatchUpTerm', 'To catch up after waiting, contribute per ' + FREQ_NAMES[f]);
    set('ddCatchUp', money.format(needed));
    set('ddCatchUpExtra', pmt > 0 && needed > 0 ? Math.round((needed / pmt - 1) * 100) + '% more than your planned ' + money.format(pmt)
        : 'With no regular contribution planned, this replaces the growth you missed.');

    var body = document.getElementById('ddSchedule');
    while (body.firstChild) body.removeChild(body.firstChild);
    for (var y = 1; y <= years; y++) {
      var a = fv(start, pmt, i, y * f);
      var b = y <= wait ? 0 : fv(start, pmt, i, (y - wait) * f);
      var tr = document.createElement('tr');
      cell(tr, String(y));
      cell(tr, money0.format(a));
      cell(tr, y <= wait ? 'Not started' : money0.format(b));
      cell(tr, money0.format(a - b));
      body.appendChild(tr);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ddForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
